ALTER TABLE public.meningite_cases
  ADD COLUMN IF NOT EXISTS faixa_etaria text,
  ADD COLUMN IF NOT EXISTS regional text,
  ADD COLUMN IF NOT EXISTS macroregiao text;

UPDATE public.meningite_cases
SET idade = date_part('year', age(current_date, data_nascimento))
WHERE data_nascimento IS NOT NULL AND idade IS NULL;

UPDATE public.meningite_cases
SET faixa_etaria = CASE
  WHEN idade < 1 THEN '< 1 ano'
  WHEN idade <= 10 THEN '1 a 10 anos'
  WHEN idade <= 20 THEN '11 a 20 anos'
  WHEN idade <= 30 THEN '21 a 30 anos'
  WHEN idade <= 40 THEN '31 a 40 anos'
  WHEN idade <= 50 THEN '41 a 50 anos'
  WHEN idade <= 60 THEN '51 a 60 anos'
  WHEN idade <= 70 THEN '61 a 70 anos'
  ELSE 'Acima de 70 anos' END
WHERE idade IS NOT NULL AND faixa_etaria IS NULL;

