UPDATE public.meningite_cases c
SET regional = m.reg, macroregiao = m.macro
FROM m
WHERE m.mun = translate(upper(btrim(c.municipio_residencia)), 'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑ', 'AAAAAEEEEIIIIOOOOOUUUUCN')
  AND (c.regional IS NULL OR c.macroregiao IS NULL);